import Foundation

func at(_ value: String) -> Date { ISO8601DateFormatter().date(from: value)! }
func check(_ condition: @autoclosure () -> Bool, _ message: String) { if !condition() { fatalError(message) } }
let basic = RoutineCalendar(timezone: "America/New_York", start: "07:30", cutoff: "20:00", days: Array(repeating: nil, count: 7), scheduleOnly: false)
func locked(_ now: String, day: String = "2026-10-23", grant: Bool = false, until: String = "2026-10-24T00:00:00Z", calendar: RoutineCalendar = basic) -> Bool {
    calendar.locked(at: at(now), decisionDate: day, decisionLocked: !grant, validUntil: at(until))
}
check(basic.isValid, "ordinary household schedule must be valid")
check(!locked("2026-10-23T11:29:59Z"), "available before start even if yesterday was locked")
check(locked("2026-10-23T11:30:00Z"), "start boundary closes access without an approved grant")
check(locked("2026-10-23T11:30:00Z", grant: true, until: "2026-10-23T11:30:00Z"), "server's pre-start access expires at start and never becomes chore approval")
check(!locked("2026-10-23T12:00:00Z", grant: true), "today's approved grant unlocks the routine window")
check(locked("2026-10-24T00:00:00Z", grant: true), "cutoff closes today's grant")
check(!locked("2026-10-24T04:00:00Z", grant: true), "new day starts its pre-routine window")
check(locked("2026-10-24T11:30:00Z", grant: true), "yesterday's completed chores never grant today's access")
let noChores = RoutineCalendar(timezone: basic.timezone, start: basic.start, cutoff: basic.cutoff, days: basic.days, scheduleOnly: true)
check(!locked("2026-10-24T12:00:00Z", calendar: noChores), "explicit schedule-only policy repeats without yesterday's chores")
check(locked("2026-10-25T00:00:00Z", calendar: noChores), "schedule-only policy still closes at cutoff")
var days = basic.days; days[6] = RoutineHours(start: "09:00", cutoff: "21:30")
let weekend = RoutineCalendar(timezone: basic.timezone, start: basic.start, cutoff: basic.cutoff, days: days, scheduleOnly: true)
check(!locked("2026-10-24T12:59:00Z", calendar: weekend), "Saturday override is used in household timezone")
check(!locked("2026-10-25T01:29:59Z", calendar: weekend), "weekend end differs from daily end")
check(locked("2026-10-25T01:30:00Z", calendar: weekend), "weekend cutoff is enforced")
check(!locked("2026-11-01T12:29:59Z", day: "2026-10-31"), "fall DST uses household start offset")
check(locked("2026-11-01T12:30:00Z", day: "2026-10-31"), "fall DST start requires new approval")
check(locked("2026-03-08T11:30:00Z", day: "2026-03-07"), "spring DST start requires new approval")
let repeated = RoutineCalendar(timezone: basic.timezone, start: "00:00", cutoff: "01:30", days: basic.days, scheduleOnly: true)
check(locked("2026-11-01T06:15:00Z", calendar: repeated), "repeated clock hour never reopens a completed cutoff")
let invalid = RoutineCalendar(timezone: "not-a-timezone", start: "07:30", cutoff: "20:00", days: basic.days, scheduleOnly: true)
check(!invalid.isValid && invalid.locked(at: at("2026-10-23T12:00:00Z"), decisionDate: "2026-10-23", decisionLocked: false, validUntil: at("2026-10-24T00:00:00Z")), "invalid cached schedules fail closed")
let intervals = basic.intervals()
check(intervals.count == 15, "weekly plan fits alongside the existing grant-expiry monitor")
check(Set(intervals.map(\.name)).count == 15, "every monitor has a stable unique name")
let late = RoutineCalendar(timezone: "UTC", start: "23:55", cutoff: "23:59", days: basic.days, scheduleOnly: true)
check(late.intervals().allSatisfy { $0.durationMinutes >= 16 }, "short windows expand their callback interval to Apple's minimum")
check(late.intervals().contains { $0.start.weekday == 7 && $0.end.weekday == 1 }, "expanded Saturday callback wraps to Sunday")
let pending = RoutineCalendarSnapshot(calendar: basic, decisionDate: "2026-10-23", decisionLocked: false, validUntil: at("2026-10-24T00:00:00Z"), monitorsReady: false)
check(pending.locked(at: at("2026-10-23T12:00:00Z")), "partially installed monitors cannot grant access")
let restored = try JSONDecoder().decode(RoutineCalendarSnapshot.self, from: JSONEncoder().encode(pending))
check(restored.locked(at: at("2026-10-23T11:00:00Z")), "persisted pending installation fails closed even before the start")
let ready = RoutineCalendarSnapshot(calendar: basic, decisionDate: "2026-10-23", decisionLocked: false, validUntil: at("2026-10-24T00:00:00Z"), monitorsReady: true)
check(!ready.locked(at: at("2026-10-23T12:00:00Z")) && ready.locked(at: at("2026-10-24T12:00:00Z")), "ready snapshot preserves today's grant without carrying it into tomorrow")
print("Routine schedule: 25 checks passed")
